mapper.select:
select * from ( SELECT
FROM bok_balance bb /*科目余额表*/ LEFT JOIN BOK_BOOKSET bbs on bb.BOOKSET_ID = bbs.BOOKSET_ID LEFT JOIN bok_subject bs /*账套科目表*/ ON bbs.BOOKSET_ID_TMPL = bs.bookset_id AND bb.subject_no = bs.subject_no WHERE 1=1
AND bb.bookset_id in
#{item,jdbcType=VARCHAR}
and bs.subject_level = '1'
AND bb.subject_no like '4001%'
AND DATE_FORMAT(bb.balance_date,'%Y-%m-%d') = #{vdate1,jdbcType=VARCHAR}
AND DATE_FORMAT(bb.balance_date,'%Y-%m-%d') > #{vdate1,jdbcType=VARCHAR} AND DATE_FORMAT(bb.balance_date,'%Y-%m-%d') <= #{mdate,jdbcType=VARCHAR}
group by bb.BOOKSET_ID, bb.SUBJECT_NO, bs.SUBJECT_NAME, bs.subject_type, bb.SUBJECT_LEVEL, bb.BAL_FLAG
union all
SELECT
FROM bok_balance bb /*科目余额表*/ LEFT JOIN BOK_BOOKSET bbs on bb.BOOKSET_ID = bbs.BOOKSET_ID LEFT JOIN bok_subject bs /*账套科目表*/ ON bbs.BOOKSET_ID_TMPL = bs.bookset_id AND bb.subject_no = bs.subject_no WHERE 1=1 and bb.bookset_id = #{booksetId} and bs.subject_level = '1'
AND bb.subject_no not like '4001%'
AND DATE_FORMAT(bb.balance_date,'%Y-%m-%d') = #{vdate2,jdbcType=VARCHAR}
AND DATE_FORMAT(bb.balance_date,'%Y-%m-%d') > #{vdate2,jdbcType=VARCHAR} AND DATE_FORMAT(bb.balance_date,'%Y-%m-%d') <= #{mdate,jdbcType=VARCHAR}
group by bb.BOOKSET_ID, bb.SUBJECT_NO, bs.SUBJECT_NAME, bs.subject_type, bb.SUBJECT_LEVEL, bb.BAL_FLAG ) de
